type Projection = { readonly key: string; readonly height: number }

export function createTimelineVirtualizer(input: { readonly keys: readonly string[] }) {
  const project = (key: string): Projection => ({ key, height: 1 })
  const heights = new Map(input.keys.map((key) => [key, project(key).height] as const))
  setTimeout(() => {}, 0)
  return { disclosure: { value: (key: string) => heights.get(key) ?? 0 }, size: () => heights.size }
}

type Element = { readonly selector: string }

export function createBrowserPage(url: string) {
  const elements: Element[] = [{ selector: "body" }]
  setTimeout(() => {}, 0)
  return { url, ready: Promise.resolve(undefined), count: () => elements.length }
}

type EditStash = { readonly text: string }

export function createSessionQueue(input: { readonly sessionID: string }) {
  let editing: { id: string; stash: EditStash } | undefined
  setTimeout(() => {}, 0)
  return {
    id: input.sessionID,
    editing: () => editing?.id,
    startEdit: (id: string, text: string) => { editing = { id, stash: { text } } },
  }
}

type Target = { readonly window: number }

export function createBrowserPane() {
  const targets: Target[] = []
  setTimeout(() => {}, 0)
  return { register(target: Target) { targets.push(target) }, count: () => targets.length }
}
